#pragma once

#ifndef FUSED_ADD_RMSNORM_001_FUSED_ADD_RMSNORM_H2048_KERNEL_H
#define FUSED_ADD_RMSNORM_001_FUSED_ADD_RMSNORM_H2048_KERNEL_H

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the fused add + RMSNorm kernel for hidden_size=2048.
// Inputs and outputs are BF16; intermediate accumulation runs in FP32 per the
// precision contract (CLAUDE.md Rule 8). Output is pre-allocated by the eval
// driver and written in-place (destination-passing style).
void fused_add_rmsnorm_h2048_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& residual,
    const torch::Tensor& weight,
    torch::Tensor& output,
    float eps,
    cudaStream_t stream);

#endif  // FUSED_ADD_RMSNORM_001_FUSED_ADD_RMSNORM_H2048_KERNEL_H

#include "kernel.h"
#include <cuda_bf16.h>
#include <cuda_runtime.h>

// Each CTA processes one row of [batch, hidden_size]. Threads cooperatively
// reduce the sum-of-squares of (hidden_states + residual) in FP32, then
// rescale (hidden_states + residual) * inv_rms * weight and store in BF16.

namespace {

__device__ inline float warp_all_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_xor_sync(0xFFFFFFFFu, val, offset);
    }
    return val;
}

constexpr int HIDDEN_SIZE = 2048;
constexpr int HIDDEN_SIZE_VEC = 1024;  // BF16x2 pairs per row
constexpr int BLOCK_THREADS = 1024;
constexpr int MAX_WARPS = 32;  // covers blockDim.x up to 1024

__global__ void __launch_bounds__(BLOCK_THREADS, 1) fused_add_rmsnorm_h2048_kernel(
    const __nv_bfloat16* __restrict__ hidden_states,
    const __nv_bfloat16* __restrict__ residual,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int batch_size,
    float eps) {

    const int row = blockIdx.x;
    if (row >= batch_size) {
        return;
    }

    const __nv_bfloat162* hs_row =
        reinterpret_cast<const __nv_bfloat162*>(hidden_states) + row * HIDDEN_SIZE_VEC;
    const __nv_bfloat162* res_row =
        reinterpret_cast<const __nv_bfloat162*>(residual) + row * HIDDEN_SIZE_VEC;
    const __nv_bfloat162* w_vec =
        reinterpret_cast<const __nv_bfloat162*>(weight);
    __nv_bfloat162* out_row =
        reinterpret_cast<__nv_bfloat162*>(output) + row * HIDDEN_SIZE_VEC;

    const int tid = threadIdx.x;

    float thread_sum_sq = 0.0f;
    #pragma unroll 1
    for (int i = tid; i < HIDDEN_SIZE_VEC; i += BLOCK_THREADS) {
        __nv_bfloat162 hv = __ldg(hs_row + i);
        __nv_bfloat162 rv = __ldg(res_row + i);
        float2 h_f2 = __bfloat1622float2(hv);
        float2 r_f2 = __bfloat1622float2(rv);
        float x0 = h_f2.x + r_f2.x;
        float x1 = h_f2.y + r_f2.y;
        thread_sum_sq += x0 * x0 + x1 * x1;
    }

    thread_sum_sq = warp_all_reduce_sum(thread_sum_sq);

    __shared__ float s_warp[MAX_WARPS];
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int num_warps = (BLOCK_THREADS + 31) >> 5;
    if (lane == 0) {
        s_warp[warp] = thread_sum_sq;
    }
    __syncthreads();

    float row_sum = 0.0f;
    if (warp == 0) {
        float partial = (lane < num_warps) ? s_warp[lane] : 0.0f;
        partial = warp_all_reduce_sum(partial);
        if (lane == 0) {
            s_warp[0] = partial;
        }
    }
    __syncthreads();
    row_sum = s_warp[0];

    const float inv_rms = rsqrtf(row_sum / static_cast<float>(HIDDEN_SIZE) + eps);

    #pragma unroll 1
    for (int i = tid; i < HIDDEN_SIZE_VEC; i += BLOCK_THREADS) {
        __nv_bfloat162 hv = __ldg(hs_row + i);
        __nv_bfloat162 rv = __ldg(res_row + i);
        __nv_bfloat162 wv = __ldg(w_vec + i);
        float2 h_f2 = __bfloat1622float2(hv);
        float2 r_f2 = __bfloat1622float2(rv);
        float2 w_f2 = __bfloat1622float2(wv);
        float y0 = (h_f2.x + r_f2.x) * inv_rms * w_f2.x;
        float y1 = (h_f2.y + r_f2.y) * inv_rms * w_f2.y;
        out_row[i] = __float22bfloat162_rn(make_float2(y0, y1));
    }
}

}  // namespace

void fused_add_rmsnorm_h2048_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& residual,
    const torch::Tensor& weight,
    torch::Tensor& output,
    float eps,
    cudaStream_t stream) {

    const auto batch_size = static_cast<int>(hidden_states.size(0));
    dim3 grid(batch_size);
    dim3 block(BLOCK_THREADS);

    fused_add_rmsnorm_h2048_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(hidden_states.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(residual.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        batch_size,
        eps);
}

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

// PyBind11 entry point. The eval driver pre-allocates the output tensor and
// passes it in destination-passing style; this function writes results
// in-place and returns void per CLAUDE.md "Submission Format".

static void check_bfloat16_cuda_contiguous(const torch::Tensor& t, const char* name) {
    TORCH_CHECK(t.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(t.dtype() == torch::kBFloat16, name, " must be bfloat16");
    TORCH_CHECK(t.is_contiguous(), name, " must be contiguous");
}

void run(torch::Tensor hidden_states, torch::Tensor residual, torch::Tensor weight, torch::Tensor output) {
    check_bfloat16_cuda_contiguous(hidden_states, "hidden_states");
    check_bfloat16_cuda_contiguous(residual, "residual");
    check_bfloat16_cuda_contiguous(weight, "weight");
    check_bfloat16_cuda_contiguous(output, "output");

    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be 2-D");
    TORCH_CHECK(residual.dim() == 2, "residual must be 2-D");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1-D");
    TORCH_CHECK(output.dim() == 2, "output must be 2-D");

    const int64_t batch_size = hidden_states.size(0);
    const int64_t hidden_size = hidden_states.size(1);

    TORCH_CHECK(hidden_size == 2048, "hidden_size must be 2048, got ", hidden_size);
    TORCH_CHECK(residual.size(0) == batch_size && residual.size(1) == hidden_size,
                "residual shape mismatch");
    TORCH_CHECK(weight.size(0) == hidden_size, "weight size must equal hidden_size");
    TORCH_CHECK(output.size(0) == batch_size && output.size(1) == hidden_size,
                "output shape mismatch");

    constexpr float kEps = 1.0000000e-06f;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    fused_add_rmsnorm_h2048_launcher(
        hidden_states, residual, weight, output, kEps, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, "Fused add + RMSNorm kernel for hidden_size=2048 (BFloat16, CUDA, DPS).");
}
